        return 0;
    }

    static TreeNode build(String[] tokens, int start) {
        if (tokens.length <= start || tokens[start].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tokens[start]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = start + 1;
        while (!q.isEmpty() && i < tokens.length) {
            TreeNode node = q.poll();
            if (i < tokens.length && !tokens[i].equals("null")) {
                node.left = new TreeNode(Integer.parseInt(tokens[i]));
                q.add(node.left);
            }
            i++;
            if (i < tokens.length && !tokens[i].equals("null")) {
                node.right = new TreeNode(Integer.parseInt(tokens[i]));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        String text = new String(System.in.readAllBytes()).trim();
        String[] tokens = text.split("\\s+");
        int k = Integer.parseInt(tokens[0]);
        System.out.println(kthLargest(build(tokens, 1), k));
    }
}
